import{_ as i}from"./chunks/emo.CGwrrK0y.js";import{_ as t,o as e,c as o,a5 as s}from"./chunks/framework.D47SInms.js";const u=JSON.parse('{"title":"5. 비상 정지 및 복구","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/guides/common/emo.md","filePath":"ko/guides/common/emo.md","lastUpdated":1791600043000}'),n={name:"ko/guides/common/emo.md"};function l(r,a,c,d,g,m){return e(),o("div",null,[...a[0]||(a[0]=[s('<h1 id="_5-비상-정지-및-복구" tabindex="-1">5. 비상 정지 및 복구 <a class="header-anchor" href="#_5-비상-정지-및-복구" aria-label="Permalink to &quot;5. 비상 정지 및 복구&quot;">​</a></h1><p><strong>목표:</strong> 비상 상황에서 즉시 로봇을 정지하는 방법과 안전하게 작동을 재개하는 방법을 숙지합니다.</p><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">경고</p><p>로봇 작동 중에는 비상 정지 버튼에 항상 접근할 수 있는 상태를 유지하세요. 로봇이 사람이나 재산에 위험을 초래할 수 있는 상황에서는 즉시 비상 정지 버튼을 누르세요.</p></div></div><h2 id="물리적-비상-정지-버튼" tabindex="-1">물리적 비상 정지 버튼 <a class="header-anchor" href="#물리적-비상-정지-버튼" aria-label="Permalink to &quot;물리적 비상 정지 버튼&quot;">​</a></h2><figure><img src="'+i+'" alt="로봇 후면의 비상 정지 버튼"><figcaption style="text-align:center;">[ 비상 정지 누름 버튼 — 로봇 후면에 위치 ]</figcaption></figure><p><strong>비상 정지 버튼</strong>을 누르면:</p><ul><li>모든 관절이 <strong>High Damping</strong> 모드로 전환됩니다.</li><li>로봇은 외부 움직임에 저항하지만 토크나 위치 명령을 <strong>받지 않습니다</strong>.</li><li>자세를 유지하지 못하고 중력에 의해 바닥으로 내려앉을 수 있습니다.</li></ul><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">참고</p><p>High Damping 모드는 사용자와 로봇 모두를 보호합니다. 비상 정지가 해제되고 로봇이 재초기화될 때까지 어떤 동작 명령도 실행되지 않습니다.</p></div></div><h2 id="앱에서-비상-정지" tabindex="-1">앱에서 비상 정지 <a class="header-anchor" href="#앱에서-비상-정지" aria-label="Permalink to &quot;앱에서 비상 정지&quot;">​</a></h2><p>RBQ 앱에서는 제어 홈 상단 바 오른쪽에 <code>E-STOP</code> 버튼이 있고, 다른 화면에서도 로봇이 연결돼 있는 동안에는 같은 자리에 나옵니다. 연결이 끊겨도 8초 동안은 살아 있습니다. 확인을 거친 뒤 물리 버튼과 동일하게 모든 관절이 High Damping 모드로 전환됩니다. 확인 창과 다른 기기가 제어권을 가져갔을 때의 동작은 <strong><a href="/RBQ/nightly/ko/manual/gui/emergency.html">비상 정지</a></strong> 페이지에, 강제 복구 도구는 <strong><a href="/RBQ/nightly/ko/manual/gui/developer-mode.html#emergency">개발자 모드</a></strong> 페이지에 있습니다.</p><h2 id="복구-절차" tabindex="-1">복구 절차 <a class="header-anchor" href="#복구-절차" aria-label="Permalink to &quot;복구 절차&quot;">​</a></h2><p>비상 정지 후 다음 단계에 따라 안전하게 작동을 재개합니다:</p><ol><li><strong>안전 확인</strong> — 로봇 주변 2m 이내에 사람이나 동물이 없는지 확인합니다.</li><li><strong>버튼 해제</strong> — 물리적 비상 정지 버튼을 시계 방향으로 돌려 잠금 해제합니다.</li><li><strong>초기 자세로 복귀</strong> — 로봇이 넘어지거나 위치가 바뀐 경우, 평평한 바닥에서 <a href="/RBQ/nightly/ko/guides/common/initial-pose.html">올바른 초기 자세</a>로 수동으로 되돌립니다.</li><li><strong>재초기화</strong> — <a href="/RBQ/nightly/ko/manual/gui/control-home.html">제어 홈</a>에서 자동 기동 시퀀스나 Stand 모션을 실행합니다.</li><li><strong>확인</strong> — 작동 재개 전 상단 바의 로봇 상태가 정상이고 기동 항목이 모두 완료되었는지 확인합니다.</li></ol><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>High Damping 모드 상태에서 관절을 강제로 움직이지 마세요. 비상 정지를 해제한 후 천천히 초기 자세로 복귀시키세요.</p></div></div><h2 id="관련-문서" tabindex="-1">관련 문서 <a class="header-anchor" href="#관련-문서" aria-label="Permalink to &quot;관련 문서&quot;">​</a></h2><ul><li><a href="/RBQ/nightly/ko/manual/safety/general-safety-warning-precautions.html">일반 안전 지침</a></li><li><a href="/RBQ/nightly/ko/manual/safety/emergency-stop-procedures.html">비상 정지 절차 (상세)</a></li><li><a href="/RBQ/nightly/ko/guides/common/initial-pose.html">초기 자세 설정 및 전원 켜기</a></li></ul>',16)])])}const b=t(n,[["render",l]]);export{u as __pageData,b as default};
